const pack = game.packs.get("wang-pf2e-homebrew.homebrew-items");
if (!pack) return ui.notifications.error("找不到合集，请确认模块已启用。");
const ids = ["whbJiuliLsr00001", "whbJiuliMod00001", "whbJiuliGtr00001", "whbJiuliSated001", "whbJiuliParryA01", "whbJiuliEnticA01"];
const docs = [];
for (const id of ids) {
  const d = await pack.getDocument(id);
  if (d) docs.push(d.toObject());
}
if (!docs.length) return ui.notifications.error("合集中未找到妖刀条目，请先运行 npm run pack。");
await Item.createDocuments(docs);
ui.notifications.info(`已导入 ${docs.length} 个「妖刀·隐里切」相关条目到物品目录。`);
